import re

TRE = re.compile(r'^(?P<ind> *)(?P<mark>[✔✖﹣▶])\s+(?P<name>.*?)(?:\s+\((?P<dur>[\d.]+\s*m?s)\))?(?:\s+#\s*(?P<dir>.*?))?\s*$')
SRE = re.compile(r'^ℹ\s+(?P<key>\S+)\s+(?P<value>.*\S)\s*$')
PRE = re.compile(r'^(?P<key>\w+):\s*(?P<val>.*?),?$')
STATUS = {'✔': 'pass', '✖': 'fail', '﹣': 'skip'}

def parse(lines):
    tests = []
    tl = []
    summ = {}
    sl = []
    fails = []
    fl = []
    skip = []
    stack = []
    mode = 'tests'
    cur = None
    inobj = False
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        if re.match(r'^\s*✖\s+failing tests:\s*$', l):
            mode = 'fail'
            skip.append(i)
            continue
        m = SRE.match(l)
        if m:
            summ[m.group('key')] = m.group('value')
            sl.append(i)
            continue
        if mode == 'tests':
            m = TRE.match(l)
            if not m:
                continue
            ind = len(m.group('ind'))
            if m.group('mark') == '▶':
                stack.append((ind, m.group('name')))
                tl.append(i)
                continue
            kind = 'test'
            if stack and stack[-1][0] == ind and stack[-1][1] == m.group('name'):
                stack.pop()
                kind = 'suite'
            tests.append({'suite': ' > '.join(s[1] for s in stack), 'name': m.group('name'), 'type': kind, 'status': STATUS.get(m.group('mark'), ''), 'duration': m.group('dur') or '', 'directive': m.group('dir') or ''})
            tl.append(i)
            continue
        m = re.match(r'^test at (?P<loc>\S+)\s*$', l)
        if m:
            cur = {'location': m.group('loc'), 'name': '', 'status': '', 'duration': '', 'error': '', 'frame': '', 'generatedMessage': '', 'code': '', 'actual': '', 'expected': '', 'operator': '', 'diff': ''}
            fails.append(cur)
            fl.append(i)
            inobj = False
            continue
        if cur is None:
            continue
        fl.append(i)
        m = TRE.match(l)
        if m and not cur['name']:
            cur['name'] = m.group('name')
            cur['status'] = STATUS.get(m.group('mark'), '')
            cur['duration'] = m.group('dur') or ''
            continue
        s = l.strip()
        if not cur['error']:
            cur['error'] = s
            if s.endswith(' {'):
                inobj = True
            continue
        if inobj:
            if s == '}':
                inobj = False
                continue
            m = PRE.match(s)
            if m:
                cur[m.group('key')] = m.group('val').strip("'")
            continue
        m = re.match(r'^at (.*?)(?: \{)?$', s)
        if m:
            if not cur['frame']:
                cur['frame'] = m.group(1)
            if s.endswith(' {'):
                inobj = True
            continue
    keys = []
    for f in fails:
        for k in f:
            if k not in keys:
                keys.append(k)
    fails = [{k: f.get(k, '') for k in keys} for f in fails]
    blocks = []
    if tests:
        blocks.append({'name': 'tests', 'kind': 'table', 'lines': tl, 'records': tests})
    if summ:
        blocks.append({'name': 'summary', 'kind': 'kv', 'lines': sl, 'records': [summ]})
    if fails:
        blocks.append({'name': 'failures', 'kind': 'table', 'lines': fl, 'records': fails})
    return {'blocks': blocks, 'skip': skip}
